def find_length(binary_string):
    def max_subarray_sum(arr):
        max_sum = float('-inf')
        current_sum = 0
        for num in arr:
            current_sum += num
            if current_sum > max_sum:
                max_sum = current_sum
            if current_sum < 0:
                current_sum = 0
        return max_sum

    # Convert the binary string into an array where 0 -> 1 and 1 -> -1
    transformed_array = [1 if char == '0' else -1 for char in binary_string]

    # Find the maximum subarray sum in the transformed array
    return max_subarray_sum(transformed_array)

# Example usage
assert find_length("11000010001") == 6
