def get_ludic(n):
    def generate_ludic_numbers(limit):
        # Initialize the list from 1 to limit
        ludic_numbers = list(range(1, limit + 1))
        i = 1  # Start with the second element (value 2, at index 1)

        while i < len(ludic_numbers):
            step = ludic_numbers[i]  # Current step size
            # Build a new list by skipping every "step-th" number starting from index i + step
            ludic_numbers = [
                number
                for index, number in enumerate(ludic_numbers)
                if index <= i or (index - i) % step != 0
            ]
            i += 1  # Move to the next number in the list
        return ludic_numbers

    return generate_ludic_numbers(n)

# Example usage and test
assert get_ludic(10) == [1, 2, 3, 5, 7]
