def merge_dictionaries_three(dict1, dict2, dict3):
    # Merge the three dictionaries into one by retaining the first occurrence of duplicate keys
    merged_dict = {}
    for d in (dict1, dict2, dict3):
        for key, value in d.items():
            if key not in merged_dict:
                merged_dict[key] = value
    return merged_dict

# Example usage and tests
assert merge_dictionaries_three(
    { "R": "Red", "B": "Black", "P": "Pink" },
    { "G": "Green", "W": "White" },
    { "O": "Orange", "W": "White", "B": "Black" }
) == {'R': 'Red', 'B': 'Black', 'P': 'Pink', 'G': 'Green', 'W': 'White', 'O': 'Orange'}

